#include <stdio.h>
#include <string.h>
#include <stdbool.h>
#include <stdlib.h>

#define MAX_PATTERN_LEN 64

static bool wildcard_match(const char *pat, const char *txt)
{
    size_t p_len = strlen(pat);
    size_t t_len = strlen(txt);

    bool **dp = malloc((p_len + 1) * sizeof(bool *));
    if (!dp) return false;
    for (size_t i = 0; i <= p_len; ++i) {
        dp[i] = calloc(t_len + 1, sizeof(bool));
        if (!dp[i]) {
            for (size_t k = 0; k < i; ++k) free(dp[k]);
            free(dp);
            return false;
        }
    }

    dp[0][0] = true;
    for (size_t i = 1; i <= p_len; ++i) {
        if (pat[i-1] == '*') dp[i][0] = dp[i-1][0];
        else break;
    }

    for (size_t i = 1; i <= p_len; ++i) {
        for (size_t j = 1; j <= t_len; ++j) {
            if (pat[i-1] == '*') {
                dp[i][j] = dp[i-1][j] || dp[i][j-1];
            } else if (pat[i-1] == '?') {
                dp[i][j] = dp[i-1][j-1];
            } else {
                dp[i][j] = (pat[i-1] == txt[j-1]) && dp[i-1][j-1];
            }
        }
    }

    bool result = dp[p_len][t_len];
    for (size_t i = 0; i <= p_len; ++i) free(dp[i]);
    free(dp);
    return result;
}

int main(int argc, char *argv[])
{
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }
    const char *pattern = argv[1];
    const char *text = argv[2];
    if (strlen(pattern) >= MAX_PATTERN_LEN) {
        puts("USAGE");
        return 0;
    }
    if (wildcard_match(pattern, text))
        puts("MATCH");
    else
        puts("NO_MATCH");
    return 0;
}
